package core

import (
	"encoding/base64"
	"encoding/hex"
	"sync"
)

// drpys 6 神签名用常量表。
// 与既有的 medusa 常量表同源同值，为避免文件名冲突，此处独立一份。

// hgDrpyBranch2SV 是 branch2F13 的 64 个轮常量（原始值，使用时按 countV1 右旋）。
var hgDrpyBranch2SV = [64]uint32{
	0xa7aefe20, 0x7149f1d6, 0x47e4ca07, 0xe9b58f67, 0x93b924de, 0xc614d0f5, 0x38afe0ef, 0xb2bbad73,
	0xe24444c3, 0x9d3aec9b, 0xdf7b37e4, 0xd8b16d40, 0xf8ac31b8, 0x76b9a90b, 0x31d833ee, 0x953fce64,
	0x353595a4, 0x4609c13b, 0x36925008, 0x8c6d0925, 0x5df5c177, 0x1cfbf52b, 0x8a4fa7f0, 0x114ca35e,
	0x8193f984, 0x7a7a8733, 0x316ab4d5, 0x3c20cfc9, 0xa6d84453, 0x3a18500c, 0x798ec47a, 0x97a76b28,
	0x66c4ff96, 0x51716443, 0x0dd2fc3b, 0xb5696da7, 0xbbeb3ac5, 0x5c53d204, 0xd32608ce, 0x7279b9ec,
	0xf4188ecf, 0xf7d793db, 0x332cc491, 0xab76ae15, 0x9bebe727, 0x18a01384, 0x5be9f8a7, 0x5f90a754,
	0x39b663c0, 0x36673c83, 0x7c92f514, 0x9d7d94d7, 0xe2e8d9aa, 0x5f7e9ea9, 0x7abd4551, 0x569e05da,
	0x40a25632, 0x3df5a9a5, 0xbab37d80, 0x454286dc, 0x3f5d4e78, 0x03d7b75d, 0xb1fe4af7, 0xa5ab26a3,
}

// hgDrpyBranch2OrdersHex 是 md5SumV3 的 4×64 个消息字索引（branch 2 选行用）。
const hgDrpyBranch2OrdersHex = ""

// hgDrpySBoxBase64 是 AesV3 的 4×256 字节 S 盒（按 khronos&3 选段）。
const hgDrpySBoxBase64 = ""

var (
	hgDrpyBranch2OrdersOnce sync.Once
	hgDrpyBranch2Orders     [320]byte
	hgDrpySBoxOnce          sync.Once
	hgDrpySBox              [1024]byte
)

func hgDrpyLoadBranch2Orders() [320]byte {
	hgDrpyBranch2OrdersOnce.Do(func() {
		decoded, err := hex.DecodeString(hgDrpyBranch2OrdersHex)
		if err != nil || len(decoded) != 320 {
			panic("drpy: BRANCH2_ORDERS 常量表损坏")
		}
		copy(hgDrpyBranch2Orders[:], decoded)
	})
	return hgDrpyBranch2Orders
}

func hgDrpyLoadSBox() [1024]byte {
	hgDrpySBoxOnce.Do(func() {
		decoded, err := base64.StdEncoding.DecodeString(hgDrpySBoxBase64)
		if err != nil || len(decoded) != 1024 {
			panic("drpy: AesV3 S 盒常量表损坏")
		}
		copy(hgDrpySBox[:], decoded)
	})
	return hgDrpySBox
}
